<script setup lang="ts">
import PageTitle from '../components/common/PageTitle.vue'; import { api } from '../services/api'; import { useSystemData } from '../composables/useSystemData'
const { alarms, refresh, error } = useSystemData()
async function act(id: string | undefined, type: 'ack' | 'clear') { if (!id) return; type === 'ack' ? await api.acknowledgeAlarm(id) : await api.clearAlarm(id); await refresh() }
</script>
<template><div class="view-stack"><PageTitle eyebrow="Cloud alarms" title="Alarms & Events" description="Active and cleared alarms loaded directly from ThingsBoard."/><p v-if="error" class="notice warning">{{ error }}</p><section class="raised-card table-card"><div v-if="!alarms.length" class="empty-state"><b>No alarm records returned</b><span>No simulated alarms are generated.</span></div><div v-else class="alarm-row header"><span>Alarm type</span><span>Severity</span><span>Created</span><span>Status</span><span>Actions</span></div><div v-for="alarm in alarms" :key="alarm.id?.id" class="alarm-row"><b>{{ alarm.type }}</b><span>{{ alarm.severity }}</span><span>{{ new Date(alarm.createdTime ?? alarm.startTs ?? 0).toLocaleString() }}</span><span>{{ alarm.status }}</span><span><button v-if="!alarm.acknowledged" class="text-button" @click="act(alarm.id?.id, 'ack')">Acknowledge</button><button v-if="!alarm.cleared" class="text-button coral" @click="act(alarm.id?.id, 'clear')">Clear</button></span></div></section></div></template>
